CREATE TABLE IF NOT EXISTS mentor_desk_settings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID NOT NULL REFERENCES schools(id) ON DELETE CASCADE UNIQUE, open_doubt_limit INTEGER NOT NULL DEFAULT 3, session_allowance_minutes INTEGER NOT NULL DEFAULT 120, urgent_passes_per_week INTEGER NOT NULL DEFAULT 1, escalation_threshold_minutes INTEGER NOT NULL DEFAULT 30, week_start_day INTEGER NOT NULL DEFAULT 1, session_lengths INTEGER[] NOT NULL DEFAULT '{15,30}', verification_code_digits INTEGER NOT NULL DEFAULT 6, code_visible_minutes_before INTEGER NOT NULL DEFAULT 10, max_verification_attempts INTEGER NOT NULL DEFAULT 5, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
